import hashlib
import os
import time
import unicodedata
from typing import Optional, Dict, Tuple
import secrets
import hmac


class UserStore:
    """Persistent user storage with secure password handling."""

    def __init__(self):
        self._users: Dict[str, dict] = {}
        self._sessions: Dict[str, dict] = {}
        self._failed_attempts: Dict[str, list] = {}

    def _hash_password(self, password: str, salt: bytes) -> bytes:
        """Derive key using PBKDF2-HMAC-SHA256."""
        return hashlib.pbkdf2_hmac(
            'sha256',
            password.encode('utf-8'),
            salt,
            iterations=100000
        )

    def register_user(self, username: str, password: str, role: str = 'user') -> bool:
        """Register a new user with normalized username."""
        # Normalize username for consistent storage
        normalized = unicodedata.normalize('NFKC', username.strip().lower())

        if normalized in self._users:
            return False

        if len(normalized) < 3 or len(normalized) > 64:
            return False

        if not all(c.isalnum() or c in ('_', '-', '.') for c in normalized):
            return False

        salt = os.urandom(32)
        pw_hash = self._hash_password(password, salt)

        self._users[normalized] = {
            'password_hash': pw_hash,
            'salt': salt,
            'role': role,
            'created_at': time.time(),
            'display_name': username  # Store original for display
        }
        return True

    def authenticate(self, username: str, password: str) -> Optional[str]:
        """Authenticate user and return session token."""
        # Rate limiting check
        client_key = username.lower().strip()
        if client_key in self._failed_attempts:
            recent = [t for t in self._failed_attempts[client_key] 
                     if time.time() - t < 300]
            self._failed_attempts[client_key] = recent
            if len(recent) >= 5:
                return None

        # Look up user with normalization
        normalized = unicodedata.normalize('NFKC', username.strip().lower())

        user = self._users.get(normalized)
        if user is None:
            # Constant-time fake computation to prevent user enumeration
            fake_salt = os.urandom(32)
            self._hash_password(password, fake_salt)
            self._record_failure(client_key)
            return None

        # Verify password
        computed = self._hash_password(password, user['salt'])
        if not hmac.compare_digest(computed, user['password_hash']):
            self._record_failure(client_key)
            return None

        # Create session
        token = secrets.token_urlsafe(32)
        self._sessions[token] = {
            'username': normalized,
            'role': user['role'],
            'created_at': time.time(),
            'last_access': time.time()
        }
        return token

    def _record_failure(self, client_key: str):
        if client_key not in self._failed_attempts:
            self._failed_attempts[client_key] = []
        self._failed_attempts[client_key].append(time.time())

    def get_session(self, token: str) -> Optional[dict]:
        """Validate session token and return session data."""
        session = self._sessions.get(token)
        if session is None:
            return None
        # Session expires after 1 hour
        if time.time() - session['created_at'] > 3600:
            del self._sessions[token]
            return None
        session['last_access'] = time.time()
        return session


class DocumentService:
    """Service for managing user documents with access control."""

    def __init__(self, user_store: UserStore):
        self._store = user_store
        self._documents: Dict[str, Dict[str, dict]] = {}  # username -> {doc_id -> doc}

    def create_document(self, token: str, title: str, content: str) -> Optional[str]:
        """Create a new document for the authenticated user."""
        session = self._store.get_session(token)
        if session is None:
            return None

        username = session['username']
        doc_id = secrets.token_hex(16)

        if username not in self._documents:
            self._documents[username] = {}

        self._documents[username][doc_id] = {
            'title': title,
            'content': content,
            'owner': username,
            'created_at': time.time()
        }
        return doc_id

    def get_document(self, token: str, owner_username: str, doc_id: str) -> Optional[dict]:
        """Retrieve a document. Users can only access their own documents
        unless they have admin role."""
        session = self._store.get_session(token)
        if session is None:
            return None

        requesting_user = session['username']
        requesting_role = session['role']

        # Authorization check: only owner or admin can access
        if requesting_role != 'admin' and requesting_user != owner_username:
            return None

        # Normalize the owner username for document lookup
        # This ensures consistent access regardless of input encoding
        lookup_key = unicodedata.normalize('NFC', owner_username)

        user_docs = self._documents.get(lookup_key)
        if user_docs is None:
            return None

        return user_docs.get(doc_id)

    def list_documents(self, token: str) -> Optional[list]:
        """List all documents for the authenticated user."""
        session = self._store.get_session(token)
        if session is None:
            return None

        username = session['username']
        user_docs = self._documents.get(username, {})
        return [{'id': did, 'title': doc['title']} for did, doc in user_docs.items()]

    def share_document(self, token: str, doc_id: str, target_user: str) -> bool:
        """Share a document with another user by creating a reference."""
        session = self._store.get_session(token)
        if session is None:
            return False

        owner = session['username']

        if owner not in self._documents or doc_id not in self._documents[owner]:
            return False

        # Normalize target for consistent storage
        target_normalized = unicodedata.normalize('NFKC', target_user.strip().lower())

        if target_normalized not in self._store._users:
            return False

        if target_normalized not in self._documents:
            self._documents[target_normalized] = {}

        # Create a copy reference
        self._documents[target_normalized][doc_id] = self._documents[owner][doc_id].copy()
        return True
